def main(extract_md) -> dict:
    import datetime
    import re

    def parse_lines(text):
        info = {"地点": "", "日期": "", "意图": ""}
        for line in str(text or "").splitlines():
            line = line.strip()
            if not line or ":" not in line:
                continue
            key, _, value = line.partition(":")
            key = key.strip()
            value = value.strip()
            if key in info:
                info[key] = value
        return info

    loc_map = {
        "青岛": ("370200", "青岛市"), "青岛市": ("370200", "青岛市"), "青岛地区": ("370200", "青岛市"),
        "市南": ("370202", "市南区"), "市南区": ("370202", "市南区"),
        "市北": ("370203", "市北区"), "市北区": ("370203", "市北区"),
        "黄岛": ("370211", "黄岛区"), "黄岛区": ("370211", "黄岛区"),
        "西海岸": ("370211", "黄岛区"), "西海岸新区": ("370211", "黄岛区"),
        "崂山": ("370212", "崂山区"), "崂山区": ("370212", "崂山区"),
        "李沧": ("370213", "李沧区"), "李沧区": ("370213", "李沧区"),
        "城阳": ("370214", "城阳区"), "城阳区": ("370214", "城阳区"),
        "即墨": ("370215", "即墨区"), "即墨区": ("370215", "即墨区"), "即墨市": ("370215", "即墨区"),
        "胶州": ("370281", "胶州市"), "胶州市": ("370281", "胶州市"),
        "平度": ("370283", "平度市"), "平度市": ("370283", "平度市"),
        "莱西": ("370285", "莱西市"), "莱西市": ("370285", "莱西市"),
    }

    def match_loc(text):
        text = str(text or "").strip()
        if not text:
            return ("370200", "青岛市")
        if text in loc_map:
            return loc_map[text]
        for suffix in ("新区", "区", "市"):
            if text.endswith(suffix) and len(text) > len(suffix):
                root = text[:-len(suffix)]
                if root in loc_map:
                    return loc_map[root]
        return None

    ch_num = {"一": 0, "二": 1, "三": 2, "四": 3, "五": 4, "六": 5, "日": 6, "天": 6, "末": 6}

    def parse_date(date_text, intent):
        today = datetime.date.today()
        if intent != "预报":
            return (0, f"现在(实况,{today})", False)
        text = str(date_text or "").strip()
        if not text or text in ("今天", "今日", "当天", "今儿"):
            return (0, f"今天({today})", False)
        if text in ("明天", "明日", "次日", "明儿"):
            return (1, f"明天({today + datetime.timedelta(days=1)})", False)
        if text == "后天":
            return (2, f"后天({today + datetime.timedelta(days=2)})", False)
        if text in ("大后天", "外后天", "三后天"):
            return (3, f"大后天({today + datetime.timedelta(days=3)})", False)
        wd_keys = {
            "周一": 0, "周二": 1, "周三": 2, "周四": 3, "周五": 4, "周六": 5, "周日": 6, "星期天": 6,
            "星期一": 0, "星期二": 1, "星期三": 2, "星期四": 3, "星期五": 4, "星期六": 5, "星期日": 6,
        }
        if text in wd_keys:
            delta = (wd_keys[text] - today.weekday()) % 7
            return (delta, f"{text}({today + datetime.timedelta(days=delta)})", delta > 3)
        m = re.match(r"^下周(.+)$", text)
        if m and m.group(1) in ch_num:
            delta = (ch_num[m.group(1)] - today.weekday()) % 7
            if delta == 0:
                delta = 7
            return (delta, f"{text}({today + datetime.timedelta(days=delta)})", delta > 3)
        m = re.match(r"^(\d{4})[-/年](\d{1,2})[-/月](\d{1,2})日?$", text)
        if m:
            target = datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
            delta = (target - today).days
            return (delta, f"{text}({target})", delta < 0 or delta > 3)
        m = re.match(r"^(\d{1,2})月(\d{1,2})日?$", text)
        if m:
            target = datetime.date(today.year, int(m.group(1)), int(m.group(2)))
            if target < today:
                target = datetime.date(today.year + 1, int(m.group(1)), int(m.group(2)))
            delta = (target - today).days
            return (delta, f"{text}({target})", delta < 0 or delta > 3)
        m = re.match(r"^(\d{1,2})[-./](\d{1,2})$", text)
        if m:
            target = datetime.date(today.year, int(m.group(1)), int(m.group(2)))
            if target < today:
                ny, nm = today.year, today.month + 1
                if nm > 12:
                    ny, nm = ny + 1, 1
                target = datetime.date(ny, nm, int(m.group(2)))
            delta = (target - today).days
            return (delta, f"{text}({target})", delta < 0 or delta > 3)
        m = re.match(r"^(\d{1,2})[号日]$", text)
        if m:
            da = int(m.group(1))
            target = datetime.date(today.year, today.month, da)
            if target < today:
                ny, nm = today.year, today.month + 1
                if nm > 12:
                    ny, nm = ny + 1, 1
                target = datetime.date(ny, nm, da)
            delta = (target - today).days
            return (delta, f"{text}({target})", delta < 0 or delta > 3)
        return (0, text, True)

    info = parse_lines(extract_md)
    addr_raw = info["地点"]
    date_raw = info["日期"]
    intent_raw = info["意图"] or "实况"
    intent = "预报" if "预" in intent_raw else "实况"

    loc = match_loc(addr_raw)
    if loc is None:
        return {
            "adcode": "",
            "extensions": "base",
            "day_index": 0,
            "addr_label": addr_raw,
            "date_label": "",
            "intent": intent,
            "out_of_range": False,
            "not_supported": True,
            "parse_err": ""
        }

    adcode, addr_label = loc
    day_index, date_label, out_of_range = parse_date(date_raw, intent)
    extensions = "base" if (intent == "实况" or out_of_range) else "all"
    if out_of_range:
        extensions = "base"
        day_index = 0

    return {
        "adcode": adcode,
        "extensions": extensions,
        "day_index": day_index,
        "addr_label": addr_label,
        "date_label": date_label,
        "intent": intent,
        "out_of_range": out_of_range,
        "not_supported": False,
        "parse_err": ""
    }

def main(adcode, extensions, day_index, not_supported) -> dict:
    import os
    import json
    import urllib.request
    import urllib.parse

    if not_supported or not adcode:
        return {"raw_json": "", "api_ok": False, "api_err": "非青岛地区", "used_adcode": ""}

    key = os.environ.get("AMAP_KEY", "29cf10142e91a9f2dbd8fa0f3742bd6b")
    if not key:
        return {"raw_json": "", "api_ok": False, "api_err": "未配置AMAP_KEY", "used_adcode": ""}

    def query(ac, ext):
        params = urllib.parse.urlencode({
            "city": ac, "key": key, "extensions": ext, "output": "JSON"
        })
        url = "https://restapi.amap.com/v3/weather/weatherInfo?" + params
        with urllib.request.urlopen(url, timeout=10) as resp:
            return resp.read().decode("utf-8")

    try:
        raw = query(adcode, extensions)
        obj = json.loads(raw)
        if str(obj.get("status", "")) != "1":
            return {"raw_json": raw, "api_ok": False, "api_err": str(obj.get("info", "status非1")), "used_adcode": adcode}
        if extensions == "base":
            lives = obj.get("lives") or []
            first = lives[0] if lives else None
            empty = not isinstance(first, dict)
        else:
            fcs = obj.get("forecasts") or []
            casts = fcs[0].get("casts", []) if fcs and isinstance(fcs[0], dict) else []
            empty = len(casts) == 0
        if empty:
            raw = query("370200", extensions)
            return {"raw_json": raw, "api_ok": True, "api_err": "", "used_adcode": "370200"}
        return {"raw_json": raw, "api_ok": True, "api_err": "", "used_adcode": adcode}
    except Exception as exc:
        return {"raw_json": "", "api_ok": False, "api_err": str(exc), "used_adcode": adcode}

def main(raw_json, extensions, day_index, addr_label, date_label, used_adcode, not_supported, out_of_range) -> dict:
    import json

    if not_supported:
        return {
            "weather_packet": {"supported": False, "addr": addr_label},
            "weather_summary": f"用户询问的是{addr_label}，不在青岛地区支持范围内。应礼貌拒绝并说明本服务仅支持青岛地区天气查询。",
            "parse_err": ""
        }
    try:
        obj = json.loads(raw_json) if raw_json else {}
    except Exception as exc:
        return {"weather_packet": {}, "weather_summary": "天气数据解析失败", "parse_err": str(exc)}
    if str(obj.get("status", "")) != "1":
        return {"weather_packet": {}, "weather_summary": "天气接口返回失败", "parse_err": str(obj.get("info", ""))}

    fallback_note = ""
    if used_adcode == "370200" and addr_label != "青岛市":
        fallback_note = f"（{addr_label}暂无独立数据，已回退青岛市级）"

    if extensions == "base":
        lives = obj.get("lives") or []
        live = lives[0] if lives and isinstance(lives[0], dict) else {}
        packet = {
            "type": "实况",
            "city": live.get("city", ""),
            "weather": live.get("weather", ""),
            "temperature": live.get("temperature", ""),
            "winddirection": live.get("winddirection", ""),
            "windpower": live.get("windpower", ""),
            "humidity": live.get("humidity", ""),
            "reporttime": live.get("reporttime", "")
        }
        if out_of_range:
            summary = (
                f"用户询问{addr_label}{date_label}的天气，该日期超出高德3天预报范围，无法提供该日预报。{fallback_note}\n"
                f"当前实况：{live.get('weather','')}，气温{live.get('temperature','')}℃，"
                f"{live.get('winddirection','')}风{live.get('windpower','')}级，湿度{live.get('humidity','')}%"
            )
        else:
            summary = (
                f"地区：{addr_label}{fallback_note}\n"
                f"时间：{date_label}（数据发布{live.get('reporttime','')}）\n"
                f"天气：{live.get('weather','')}，气温{live.get('temperature','')}℃，"
                f"{live.get('winddirection','')}风{live.get('windpower','')}级，湿度{live.get('humidity','')}%"
            )
        return {"weather_packet": packet, "weather_summary": summary, "parse_err": ""}

    fcs = obj.get("forecasts") or []
    casts = fcs[0].get("casts", []) if fcs and isinstance(fcs[0], dict) else []
    cast = casts[day_index] if 0 <= day_index < len(casts) and isinstance(casts[day_index], dict) else {}
    if not cast:
        return {
            "weather_packet": {"type": "预报", "addr": addr_label, "date": date_label},
            "weather_summary": f"未获取到{addr_label}{date_label}的预报数据。{fallback_note}",
            "parse_err": ""
        }
    packet = {
        "type": "预报",
        "city": fcs[0].get("city", ""),
        "date": cast.get("date", ""),
        "week": cast.get("week", ""),
        "dayweather": cast.get("dayweather", ""),
        "nightweather": cast.get("nightweather", ""),
        "daytemp": cast.get("daytemp", ""),
        "nighttemp": cast.get("nighttemp", ""),
        "daywind": cast.get("daywind", ""),
        "nightwind": cast.get("nightwind", ""),
        "daypower": cast.get("daypower", ""),
        "nightpower": cast.get("nightpower", "")
    }
    summary = (
        f"地区：{addr_label}{fallback_note}\n"
        f"日期：{date_label}（{cast.get('date','')} 星期{cast.get('week','')}）\n"
        f"白天：{cast.get('dayweather','')}，{cast.get('daytemp','')}℃，{cast.get('daywind','')}风{cast.get('daypower','')}级\n"
        f"夜间：{cast.get('nightweather','')}，{cast.get('nighttemp','')}℃，{cast.get('nightwind','')}风{cast.get('nightpower','')}级"
    )
    return {"weather_packet": packet, "weather_summary": summary, "parse_err": ""}

